using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Experimental.Rendering;
internal class CommandScript : IRunCommand
{
    // Value-type fields use default sequential layout: 2 matrices + 2 vectors = 160 bytes. ABI matches HLSL VividVSMProjection.
    struct Projection { public Matrix4x4 worldToClip, worldToShadow; public Vector4 sphere, parameters; }
    // Four uint fields = 16 bytes, matching HLSL uint4. No runtime interop API is needed.
    struct U4 { public uint x, y, z, w; }
    const string Output = "Packages/VividRP/Roadmap~/Experiments/VSMCapacityCostDynamic_20260912/";
    public void Execute(ExecutionResult result)
    {
        var owned = new List<UnityEngine.Object>();
        var buffers = new List<GraphicsBuffer>();
        var cmd = new CommandBuffer { name = "Independent VSM geometric-reference GPU fixtures" };
        RayTracingAccelerationStructure acceleration = null;
        var report = new StringBuilder();
        int cases = 0;
        try
        {
            Directory.CreateDirectory(Output);
            if (!SystemInfo.supportsRayTracing) throw new Exception("Ray tracing unavailable.");
            var asset = AssetDatabase.LoadAssetAtPath<ComputeShader>(
                "Packages/com.vivid.render-pipelines/Editor/Tools/VSMBaselineReference.compute");
            if (asset == null) throw new Exception("Reference shader not imported.");
            var shader = UnityEngine.Object.Instantiate(asset); owned.Add(shader);
            var fixtureAsset = AssetDatabase.LoadAssetAtPath<ComputeShader>(
                "Packages/com.vivid.render-pipelines/Editor/Tools/VSMReferenceFixture.compute");
            if (fixtureAsset == null) throw new Exception("Reference fixture upload shader not imported.");
            var fixture = UnityEngine.Object.Instantiate(fixtureAsset); owned.Add(fixture);
            int uploadKernel = fixture.FindKernel("UploadReferencePools");
            var materialShader = Shader.Find("Hidden/InternalErrorShader");
            if (materialShader == null) throw new Exception("Fixture material shader unavailable.");
            var material = new Material(materialShader); owned.Add(material);
            GraphicsBuffer Buffer(int count, int stride)
            {
                var value = new GraphicsBuffer(GraphicsBuffer.Target.Structured, count, stride);
                buffers.Add(value); return value;
            }
            RenderTexture OutputTexture(int width, int height)
            {
                var value = new RenderTexture(new RenderTextureDescriptor(width, height,
                    GraphicsFormat.R32G32B32A32_SFloat, 0) { enableRandomWrite = true });
                owned.Add(value);
                if (!value.Create()) throw new Exception("Output texture creation failed.");
                return value;
            }
            Vector4[] ReadTexture(RenderTexture value)
            {
                var request = AsyncGPUReadback.Request(value); request.WaitForCompletion();
                if (request.hasError) throw new Exception("Texture readback failed.");
                return request.GetData<Vector4>().ToArray();
            }
            void Equal(float actual, float expected, string label, float tolerance = 0.00001f)
            {
                if (float.IsNaN(actual) || float.IsInfinity(actual) || Mathf.Abs(actual - expected) > tolerance)
                    throw new Exception(label + " actual=" + actual + " expected=" + expected);
            }
            float Plane(int layer) { return 0.95f - layer * 0.01f; }
            UnityEngine.Mesh Geometry(int count)
            {
                // Every test ray intersects the triangle strictly in its interior.
                // Repeat its index triplet so candidate count differs from unique depth.
                var vertices = new Vector3[count * 3];
                var triangles = new int[count * 6];
                for (int i = 0; i < count; i++)
                {
                    float z = Plane(i);
                    vertices[i * 3] = new Vector3(-10, -10, z);
                    vertices[i * 3 + 1] = new Vector3(20, -10, z);
                    vertices[i * 3 + 2] = new Vector3(-10, 20, z);
                    for (int copy = 0; copy < 2; copy++)
                        for (int j = 0; j < 3; j++) triangles[i * 6 + copy * 3 + j] = i * 3 + j;
                }
                var mesh = new UnityEngine.Mesh { name = "Temporary independent VSM depth planes" };
                mesh.vertices = vertices; mesh.triangles = triangles; mesh.RecalculateBounds();
                owned.Add(mesh); return mesh;
            }
            RenderTexture Pool()
            {
                var value = new RenderTexture(new RenderTextureDescriptor(1, 1, GraphicsFormat.R32_UInt, 0)
                { enableRandomWrite = true, dimension = TextureDimension.Tex2DArray, volumeDepth = 16 });
                owned.Add(value);
                if (!value.Create()) throw new Exception("Fixture uint LoadStore array creation failed.");
                return value;
            }
            var staticPool = Pool(); var dynamicPool = Pool();
            var uploadBuffer = Buffer(32,4); var uploadBits = new uint[32];
            void UploadPools(int staticCount, int dynamicCount)
            {
                for (int pool = 0; pool < 2; pool++)
                    for (int layer = 0; layer < 16; layer++)
                        uploadBits[pool*16+layer] = layer < (pool == 0 ? staticCount : dynamicCount)
                            ? unchecked((uint)BitConverter.SingleToInt32Bits(Plane(layer))) : 0u;
                uploadBuffer.SetData(uploadBits);
                cmd.SetComputeBufferParam(fixture,uploadKernel,"_ReferenceFixtureDepthBits",uploadBuffer);
                cmd.SetComputeTextureParam(fixture,uploadKernel,"_ReferenceFixtureStatic",staticPool);
                cmd.SetComputeTextureParam(fixture,uploadKernel,"_ReferenceFixtureDynamic",dynamicPool);
                cmd.DispatchCompute(fixture,uploadKernel,1,1,1);
            }
            var owners = Buffer(1, 4); owners.SetData(new uint[] { 1 });
            var table = Buffer(1, 4); table.SetData(new uint[] { 1 });
            var projections = Buffer(1, 160);
            projections.SetData(new[] { new Projection { worldToClip = Matrix4x4.identity,
                worldToShadow = Matrix4x4.identity, sphere = new Vector4(0,0,0,-1),
                parameters = new Vector4(1,0,0,1) } });
            var counts = Buffer(2, 16); var diagnostics = Buffer(2, 16); var depths = Buffer(128, 4);
            int capacityKernel = shader.FindKernel("ReferenceCapacity");
            int receiverKernel = shader.FindKernel("ReferenceReceivers");
            void BindCapacity()
            {
                cmd.SetRayTracingAccelerationStructure(shader, capacityKernel, "_ReferenceAcceleration", acceleration);
                cmd.SetComputeBufferParam(shader, capacityKernel, "_VSMProjections", projections);
                cmd.SetComputeBufferParam(shader, capacityKernel, "_VSMPrototypePhysicalPageOwners", owners);
                cmd.SetComputeBufferParam(shader, capacityKernel, "_VSMPrototypePageTable", table);
                cmd.SetComputeTextureParam(shader, capacityKernel, "_VSMPrototypeStaticPhysicalPage", staticPool);
                cmd.SetComputeTextureParam(shader, capacityKernel, "_VSMPrototypeDynamicPhysicalPage", dynamicPool);
                cmd.SetComputeBufferParam(shader, capacityKernel, "_CapacityCounts", counts);
                cmd.SetComputeBufferParam(shader, capacityKernel, "_CapacityDiagnostics", diagnostics);
                cmd.SetComputeBufferParam(shader, capacityKernel, "_CapacityReferenceDepths", depths);
                foreach (string name in new[] { "_VSMProjectionCount", "_VSMPrototypePageSize",
                    "_VSMPrototypePagesPerAxis", "_VSMPrototypeVirtualResolution",
                    "_VSMPrototypePhysicalPagesPerRow", "_VSMPrototypePhysicalPageCapacity",
                    "_VSMPrototypePageTableEntryCount", "_CapacitySamplesPerPageAxis", "_CapacityStaticMask" })
                    cmd.SetComputeIntParam(shader, name, 1);
                cmd.SetComputeIntParam(shader, "_CapacityDynamicMask", 2);
                cmd.SetComputeFloatParam(shader, "_CapacityUniqueDepthToleranceWorld", 0.0001f);
                cmd.SetComputeFloatParam(shader, "_CapacityProductionMatchToleranceWorld", 0.001f);
            }
            int[,] combinations = { {1,0}, {0,1}, {16,1}, {17,16}, {64,17}, {65,64}, {1,65} };
            for (int test = 0; test < combinations.GetLength(0); test++)
            {
                acceleration?.Dispose();
                acceleration = new RayTracingAccelerationStructure(new RayTracingAccelerationStructure.Settings(
                    RayTracingAccelerationStructure.ManagementMode.Manual,
                    RayTracingAccelerationStructure.RayTracingModeMask.Everything, -1));
                for (int pool = 0; pool < 2; pool++)
                {
                    int count = combinations[test, pool];
                    if (count != 0)
                    {
                        var config = new RayTracingMeshInstanceConfig { mesh = Geometry(count), meshLod = -1,
                            subMeshIndex = 0, material = material, mask = (uint)(1 << pool),
                            enableTriangleCulling = false, subMeshFlags = RayTracingSubMeshFlags.Enabled };
                        acceleration.AddInstance(in config, Matrix4x4.identity, null, 0);
                    }
                }
                UploadPools(combinations[test,0], combinations[test,1]);
                cmd.BuildRayTracingAccelerationStructure(acceleration);
                BindCapacity(); cmd.DispatchCompute(shader, capacityKernel, 1, 1, 1);
                Graphics.ExecuteCommandBuffer(cmd); cmd.Clear();
                var actualCounts = new U4[2]; counts.GetData(actualCounts);
                var actualDiagnostics = new Vector4[2]; diagnostics.GetData(actualDiagnostics);
                var actualDepths = new float[128]; depths.GetData(actualDepths);
                for (int pool = 0; pool < 2; pool++)
                {
                    int distinct = combinations[test,pool];
                    int occupied = Math.Min(distinct,16), retained = Math.Min(distinct,64);
                    var value = actualCounts[pool]; var diagnostic = actualDiagnostics[pool];
                    // FORCE_NON_OPAQUE traversal must enumerate each duplicated triangle,
                    // while unique bucket counting and top-16 matching discard repetition.
                    Equal(value.x, distinct * 2, "candidate count case=" + test + " pool=" + pool);
                    Equal(value.y, Math.Min(distinct,65), "unique lower bound");
                    Equal(value.z, occupied, "production occupied");
                    Equal(value.w, occupied, "production matched");
                    Equal(diagnostic.z, 0, "missing nearest16");
                    Equal(diagnostic.w, distinct > 64 ? 3 : 1, "capacity flags");
                    Equal(diagnostic.x, distinct == 0 ? -1 : 0, "maximum matched error");
                    Equal(diagnostic.y, distinct == 0 ? -1 : 0, "mean matched error");
                    for (int layer = 0; layer < 64; layer++)
                        Equal(actualDepths[pool * 64 + layer], layer < retained ? 1 - Plane(layer) : -1,
                            "reference distance case=" + test + " pool=" + pool + " layer=" + layer);
                    report.AppendLine("capacity case=" + test + " pool=" + pool + " candidates=" + value.x
                        + " uniqueLowerBound=" + value.y + " occupied/matched=" + value.z + "/" + value.w
                        + " flags=" + diagnostic.w);
                    cases++;
                }
            }
            // Empty/unowned output must overwrite prior nonempty results.
            owners.SetData(new uint[] { 0 }); BindCapacity();
            cmd.DispatchCompute(shader, capacityKernel, 1, 1, 1);
            Graphics.ExecuteCommandBuffer(cmd); cmd.Clear();
            var emptyCounts = new U4[2]; counts.GetData(emptyCounts);
            var emptyDiagnostics = new Vector4[2]; diagnostics.GetData(emptyDiagnostics);
            var emptyDepths = new float[128]; depths.GetData(emptyDepths);
            for (int pool = 0; pool < 2; pool++)
            {
                Equal(emptyCounts[pool].x + emptyCounts[pool].y + emptyCounts[pool].z + emptyCounts[pool].w,
                    0, "unowned counts");
                Equal(emptyDiagnostics[pool].w, 0, "unowned validity");
            }
            foreach (float value in emptyDepths) Equal(value, -1, "unowned depth");
            report.AppendLine("unowned slot overwrites prior outputs"); cases++;

            const int width = 4, height = 4, grid = 3;
            var deviceDepth = new Texture2D(width, height, TextureFormat.RFloat, false, true);
            var normal = new Texture2D(width, height, TextureFormat.RGBAFloat, false, true);
            var shadow = new Texture2D(width, height, TextureFormat.RFloat, false, true);
            var history = new Texture2D(width, height, TextureFormat.RGBAFloat, false, true);
            owned.Add(deviceDepth); owned.Add(normal); owned.Add(shadow); owned.Add(history);
            var inputDepth = new float[16]; var inputShadow = new float[16];
            var inputNormal = new Color[16]; var inputHistory = new Color[16];
            for (int i = 0; i < 16; i++)
            {
                inputDepth[i] = 0.2f; inputShadow[i] = 0.1f + i * 0.01f;
                inputNormal[i] = new Color(0.5f,1,0,0); // exact +Y oct normal
                inputHistory[i] = new Color(0.7f,2 + (i % 3),0.5f,1);
            }
            inputDepth[15] = 0; // sampled sky pixel (3,3).
            deviceDepth.SetPixelData(inputDepth,0); deviceDepth.Apply();
            normal.SetPixels(inputNormal); normal.Apply();
            shadow.SetPixelData(inputShadow,0); shadow.Apply();
            history.SetPixels(inputHistory); history.Apply();
            var reference = OutputTexture(grid,grid);
            var signal = OutputTexture(grid,grid); var world = OutputTexture(grid,grid);
            for (int test = 0; test < 3; test++)
            {
                bool blocked = test != 0;
                bool hasHistory = test != 2;
                cmd.SetRayTracingAccelerationStructure(shader, receiverKernel, "_ReferenceAcceleration", acceleration);
                cmd.SetComputeTextureParam(shader, receiverKernel, "_ReferenceDepthTexture", deviceDepth);
                cmd.SetComputeTextureParam(shader, receiverKernel, "_ReferenceGBuffer1", normal);
                cmd.SetComputeTextureParam(shader, receiverKernel, "_ReferenceVisibility", reference);
                cmd.SetComputeTextureParam(shader, receiverKernel, "_BaselineShadowTexture", shadow);
                cmd.SetComputeTextureParam(shader, receiverKernel, "_BaselineHistory", history);
                cmd.SetComputeTextureParam(shader, receiverKernel, "_BaselineSignal", signal);
                cmd.SetComputeTextureParam(shader, receiverKernel, "_BaselineWorld", world);
                cmd.SetComputeIntParam(shader, "_BaselineHasHistory", hasHistory ? 1 : 0);
                cmd.SetComputeIntParam(shader, "_ReferenceScreenWidth", width);
                cmd.SetComputeIntParam(shader, "_ReferenceScreenHeight", height);
                cmd.SetComputeIntParam(shader, "_ReferenceROIOriginX", 1);
                cmd.SetComputeIntParam(shader, "_ReferenceROIOriginY", 1);
                cmd.SetComputeIntParam(shader, "_ReferenceGridWidth", grid);
                cmd.SetComputeIntParam(shader, "_ReferenceGridHeight", grid);
                cmd.SetComputeIntParam(shader, "_ReferencePixelStride", 2);
                cmd.SetComputeIntParam(shader, "_ReferenceRayCount", test == 2 ? 1024 : 256);
                cmd.SetComputeMatrixParam(shader, "_ReferenceInvViewProjection", Matrix4x4.identity);
                cmd.SetComputeVectorParam(shader, "_ReferenceNormalBias", new Vector4(0.001f,0.01f,0,0));
                cmd.SetComputeVectorParam(shader, "_ReferenceLightDirection", blocked ? Vector3.forward : Vector3.back);
                cmd.SetComputeVectorParam(shader, "_ReferenceSunBasisX", Vector3.right);
                cmd.SetComputeVectorParam(shader, "_ReferenceSunBasisY", Vector3.up);
                cmd.SetComputeFloatParam(shader, "_ReferenceTanAngularRadius", 0.062f);
                cmd.SetComputeFloatParam(shader, "_ReferenceRayMaxDistance", 10);
                cmd.DispatchCompute(shader, receiverKernel, 1, 1, 1);
                Graphics.ExecuteCommandBuffer(cmd); cmd.Clear();
                var actualReference = ReadTexture(reference); var actualSignal = ReadTexture(signal);
                var actualWorld = ReadTexture(world);
                for (int gy = 0; gy < grid; gy++)
                    for (int gx = 0; gx < grid; gx++)
                    {
                        int pixelX = 1 + gx * 2, pixelY = 1 + gy * 2, outputIndex = gy * grid + gx;
                        bool inBounds = pixelX < width && pixelY < height;
                        bool valid = inBounds && inputDepth[pixelY * width + pixelX] != 0;
                        for (int channel = 0; channel < 4; channel++)
                            Equal(actualReference[outputIndex][channel], valid ? (blocked ? 0 : 1) : -1,
                                "visibility test=" + test + " pixel=" + outputIndex + " channel=" + channel);
                        Equal(actualSignal[outputIndex].w, valid ? 1 : 0, "receiver validity");
                        if (!valid)
                        {
                            Equal(actualWorld[outputIndex].sqrMagnitude, 0, "invalid world");
                            continue;
                        }
                        int inputIndex = pixelY * width + pixelX;
                        Equal(actualSignal[outputIndex].x, inputShadow[inputIndex], "copied shadow");
                        Equal(actualSignal[outputIndex].y, hasHistory ? inputHistory[inputIndex].g : 0, "copied age");
                        Equal(actualSignal[outputIndex].z, 0.2f, "device depth");
                        Equal(actualWorld[outputIndex].x, (pixelX + 0.5f) / width * 2 - 1, "world X");
                        Equal(actualWorld[outputIndex].y, 1 - (pixelY + 0.5f) / height * 2, "world Y D3D");
                        Equal(actualWorld[outputIndex].z, 0.2f, "world Z");
                        Equal(actualWorld[outputIndex].w, 1, "normal Y");
                    }
                report.AppendLine("receivers test=" + test + " rays=" + (test == 2 ? 1024 : 256)
                    + " blocked=" + blocked + " history=" + hasHistory
                    + " ROI/stride, sky, bounds, signal and world exact"); cases++;
            }
            report.AppendLine("PASS cases=" + cases
                + "; actual RTAS triangles and production reference kernels dispatched on GPU; no scene objects created.");
            File.WriteAllText(Output + "reference-gpu-result.txt",report.ToString());
            result.Log(report.ToString());
        }
        catch (Exception error)
        {
            File.WriteAllText(Output + "reference-gpu-result.txt",report.ToString() + "FAIL " + error);
            throw;
        }
        finally
        {
            cmd.Clear(); cmd.Dispose();
            acceleration?.Dispose();
            foreach (var buffer in buffers) buffer.Dispose();
            for (int i=owned.Count-1;i>=0;i--) UnityEngine.Object.DestroyImmediate(owned[i]);
        }
    }
}
